#include <algorithm>
#include <atomic>
#include <iostream>
#include <thread>
#include <vector>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 1 || n > 1000) return 1;
    std::vector<long long> values;
    for (int i = 0; i < n; i++) {
        long long value = 0;
        if (!(std::cin >> value)) return 1;
        if (value < -10000 || value > 10000) return 1;
        values.push_back(value);
    }
    std::atomic<long long> total{0};
    int half = n / 2;
    std::thread worker([&values, half, &total]() {
        for (int i = 0; i < half; i++) {
            total.fetch_add(values[static_cast<std::size_t>(i)]);
        }
    });
    for (int i = half; i < n; i++) {
        total.fetch_add(values[static_cast<std::size_t>(i)]);
    }
    worker.join();
    std::sort(values.begin(), values.end());
    std::cout << total.load() << std::endl;
    for (std::size_t i = 0; i < values.size(); i++) {
        if (i > 0) std::cout << ' ';
        std::cout << values[i];
    }
    std::cout << std::endl;
    return 0;
}
